@using sv_01c3d4b089b144c697343757e84990a7.Models
@using sv_01c3d4b089b144c697343757e84990a7.Services

<div class="settings-sidebar">
    <nav class="nav flex-column">
        @foreach (var section in _sections)
        {
            <button class="nav-link settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                <span class="settings-nav-icon">@section.Icon</span>
                <span>@section.Label</span>
            </button>
        }
    </nav>
</div>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "profile";

    [Parameter]
    public EventCallback<string> OnSectionChanged { get; set; }

    private readonly record struct SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];
}

.settings-sidebar {
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    color: #495057;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.1rem;
}

@using sv_01c3d4b089b144c697343757e84990a7.Models
@using sv_01c3d4b089b144c697343757e84990a7.Services
@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
}
else
{
    <div class="section-card">
        <h4 class="section-title">Profile Settings</h4>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }
        @if (_errorMessage is not null)
        {
            <div class="alert alert-danger alert-dismissible fade show" role="alert">
                @_errorMessage
                <button type="button" class="btn-close" @onclick="() => _errorMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="avatar-preview-area">
                    <label class="form-label fw-semibold">Avatar Preview</label>
